698	            synchronized (deque) {
699	                // Deques are often empty in this path, esp with large partition counts,
700	                // so we exit early if we can.
701	                ProducerBatch batch = deque.peekFirst();
702	                if (batch == null) {
703	                    continue;
704	                }
705	
706	                waitedTimeMs = batch.waitedTimeMs(nowMs);
707	                batch.maybeUpdateLeaderEpoch(leaderEpoch);
708	                backingOff = shouldBackoff(batch.hasLeaderChangedForTheOngoingRetry(), batch, waitedTimeMs);
